<template>
  <q-page class="admin-page">
    <div v-if="auth.canPublish" class="admin-shell">
      <header class="admin-heading"><div><div class="admin-eyebrow">{{ t('admin.eyebrow') }}</div><h1>{{ t('admin.title') }}</h1><p>{{ t('admin.subtitle') }}</p></div><div class="admin-actions"><q-btn outline color="primary" icon="add" :label="t('admin.newProject')" to="/admin/projects/new" /><q-btn flat round icon="refresh" :loading="loading" @click="load" /></div></header>
      <q-banner v-if="error" rounded class="bg-red-1 text-red-9 q-mb-lg">{{ error }}</q-banner>
      <section class="dashboard-metrics"><article v-for="item in metrics" :key="item.label" class="dashboard-metric"><div class="metric-icon" :class="item.tone"><q-icon :name="item.icon" /></div><div><span>{{ item.label }}</span><strong>{{ item.value }}</strong><small>{{ item.caption }}</small></div><q-icon name="trending_up" class="metric-trend" /></article></section>
      <section class="dashboard-grid">
        <q-card flat class="dashboard-card activity-card"><q-card-section class="dashboard-card-heading"><div><div class="card-eyebrow">{{ t('admin.overviewEyebrow') }}</div><h2>{{ t('admin.overview') }}</h2></div><q-btn flat dense icon="more_horiz" /></q-card-section><q-card-section class="overview-bars"><div v-for="bar in overviewBars" :key="bar.label" class="overview-bar"><div class="overview-bar-label"><span>{{ bar.label }}</span><strong>{{ bar.value }}</strong></div><q-linear-progress rounded size="9px" :value="bar.ratio" :color="bar.color" track-color="grey-9" /></div></q-card-section></q-card>
        <q-card flat class="dashboard-card quick-card"><q-card-section class="dashboard-card-heading"><div><div class="card-eyebrow">{{ t('admin.quickActionsEyebrow') }}</div><h2>{{ t('admin.quickActions') }}</h2></div></q-card-section><q-card-section class="quick-actions"><q-btn unelevated color="primary" text-color="dark" icon="add_box" :label="t('admin.newProject')" to="/admin/projects/new" /><q-btn v-if="auth.isAdmin" flat icon="people" :label="t('admin.manageAccounts')" @click="tab = 'accounts'" /><q-btn flat icon="inventory_2" :label="t('admin.viewProjects')" @click="tab = 'projects'" /><q-btn flat icon="settings" :label="t('account.settings')" to="/account" /></q-card-section></q-card>
      </section>
      <section class="dashboard-grid q-mt-lg"><q-card flat class="dashboard-card"><q-card-section class="dashboard-card-heading"><div><div class="card-eyebrow">{{ t('admin.engagementEyebrow') }}</div><h2>{{ t('admin.engagement') }}</h2></div></q-card-section><q-card-section class="row q-col-gutter-lg"><div class="col-12 col-md-6"><div class="text-caption text-grey-6 q-mb-sm">{{ t('admin.downloadRanking') }}</div><q-list dense separator><q-item v-for="item in overview.topDownloads" :key="`download-${item.projectSlug}`"><q-item-section>{{ item.projectSlug }}</q-item-section><q-item-section side>{{ item.count }}</q-item-section></q-item><q-item v-if="!overview.topDownloads.length"><q-item-section class="text-grey-6">{{ t('admin.noDownloadEvents') }}</q-item-section></q-item></q-list></div><div class="col-12 col-md-6"><div class="text-caption text-grey-6 q-mb-sm">{{ t('admin.favoriteRanking') }}</div><q-list dense separator><q-item v-for="item in overview.topFavorites" :key="`favorite-${item.projectSlug}`"><q-item-section>{{ item.projectSlug }}</q-item-section><q-item-section side>{{ item.count }}</q-item-section></q-item><q-item v-if="!overview.topFavorites.length"><q-item-section class="text-grey-6">{{ t('admin.noFavorites') }}</q-item-section></q-item></q-list></div></q-card-section></q-card></section>
        <q-card flat class="dashboard-card records-card"><q-card-section class="dashboard-card-heading"><div><div class="card-eyebrow">{{ t('admin.contentEyebrow') }}</div><h2>{{ t('admin.content') }}</h2></div><q-tabs v-model="tab" dense active-color="primary" indicator-color="primary"><q-tab name="projects" icon="inventory_2" :label="t('admin.projects')" /><q-tab v-if="auth.isAdmin" name="reviews" icon="fact_check" :label="t('admin.reviewQueue')" /><q-tab v-if="auth.isAdmin" name="accounts" icon="people" :label="t('admin.accounts')" /><q-tab v-if="auth.isAdmin" name="settings" icon="tune" :label="t('admin.siteSettings')" /></q-tabs></q-card-section><q-separator dark /><q-tab-panels v-model="tab" animated class="dashboard-panels"><q-tab-panel name="projects" class="q-pa-none"><q-table flat dark :rows="projects" :columns="projectColumns" row-key="id" :loading="loading" class="dashboard-table"><template #body-cell-title="props"><q-td :props="props"><div class="table-project"><q-avatar size="34px" color="primary" text-color="dark">{{ props.row.title?.slice(0, 1) }}</q-avatar><div><strong>{{ props.row.title }}</strong><small>{{ props.row.slug }} · {{ statusLabel(props.row.status) }}</small></div></div></q-td></template><template #body-cell-actions="props"><q-td :props="props"><q-btn dense flat color="primary" :label="t('admin.edit')" :to="`/admin/projects/${props.row.slug}/edit`" /></q-td></template></q-table></q-tab-panel><q-tab-panel v-if="auth.isAdmin" name="reviews"><div class="row items-center q-mb-md"><div><h3 class="q-my-none">{{ t('admin.pendingContent') }}</h3><div class="text-grey-6">{{ t('admin.reviewHint') }}</div></div><q-space /><q-btn flat icon="refresh" @click="loadReviews" /></div><q-list bordered separator><q-item v-for="item in reviews" :key="`${item.type}-${item.id}`"><q-item-section><q-item-label>{{ item.title }}</q-item-label><q-item-label caption>{{ reviewTypeLabel(item.type) }} · {{ item.slug }}</q-item-label></q-item-section><q-item-section side class="row q-gutter-sm"><q-btn dense color="positive" :label="t('admin.approve')" @click="decide(item, 'approve')" /><q-btn dense outline color="negative" :label="t('admin.reject')" @click="decide(item, 'reject')" /></q-item-section></q-item><q-item v-if="!reviews.length"><q-item-section class="text-grey-6">{{ t('admin.noPendingContent') }}</q-item-section></q-item></q-list></q-tab-panel><q-tab-panel v-if="auth.isAdmin" name="accounts" class="q-pa-none"><q-table flat dark :rows="accounts" :columns="accountColumns" row-key="id" :loading="loading" class="dashboard-table"><template #body-cell-actions="props"><q-td :props="props" class="q-gutter-xs"><q-btn v-if="!props.row.verifiedAt" dense flat color="positive" :label="t('admin.approveAccount')" @click="approveAccount(props.row)" /><q-btn v-if="auth.isRoot" dense flat color="secondary" :label="t('admin.editUuid')" @click="editMinecraftUuid(props.row)" /><q-btn dense flat color="primary" :disable="props.row.id === auth.account?.id || (props.row.role === 'root' && !auth.isRoot)" :label="nextRoleLabel(props.row.role)" @click="changeRole(props.row)" /><q-btn dense flat color="negative" :disable="props.row.id === auth.account?.id || (props.row.role === 'root' && !auth.isRoot)" :label="t('admin.delete')" @click="removeAccount(props.row)" /></q-td></template></q-table></q-tab-panel><q-tab-panel v-if="auth.isAdmin" name="settings"><div v-if="settings" class="q-pa-md"><div class="text-h6 q-mb-sm">{{ t('admin.registrationPolicy') }}</div><q-toggle v-model="settings.registration.enabled" color="positive" :label="t('admin.openRegistration')" /><q-toggle v-model="settings.registration.requireInviteCode" class="q-ml-md" :label="t('admin.requireInviteCode')" /><q-toggle v-model="settings.registration.requireApproval" class="q-ml-md" :label="t('admin.requireApproval')" /><q-input v-if="settings.registration.requireInviteCode" v-model="registrationCodesText" outlined class="q-mt-sm q-mb-lg" :label="t('admin.inviteCodes')" :hint="t('admin.inviteCodesHint')" /><div v-if="auth.isRoot" class="site-identity-settings q-mb-lg"><div class="text-h6 q-mb-sm">{{ t('admin.siteIdentity') }}</div><div class="row q-col-gutter-md"><q-input v-model="settings.appearance.siteName" class="col-12 col-md-6" outlined :label="t('admin.siteName')" :hint="t('admin.siteNameHint')" /><q-input v-model="settings.appearance.siteIconUrl" class="col-12 col-md-6" outlined :label="t('admin.siteIconUrl')" :hint="t('admin.siteIconHint')" /></div><div v-if="settings.appearance.siteIconUrl" class="site-identity-preview q-mt-sm"><q-img :src="settings.appearance.siteIconUrl" fit="cover" width="42px" height="42px" :alt="settings.appearance.siteName" /><span>{{ settings.appearance.siteName }}</span></div></div><div class="text-h6 q-mb-sm">{{ t('admin.appearance') }}</div><q-toggle v-model="settings.appearance.roundedProjectIcons" color="positive" :label="t('admin.roundedIcons')" /><div class="text-caption text-grey-6 q-mb-lg">{{ t('admin.roundedIconsHint') }}</div><div class="text-h6 q-mb-md">{{ t('admin.moderationPolicy') }}</div><div class="row q-col-gutter-md"><q-select v-model="settings.moderation.projectCreation" class="col-12 col-md-6" outlined :label="t('admin.projectCreation')" :options="policyOptions" emit-value map-options /><q-select v-model="settings.moderation.fileSubmission" class="col-12 col-md-6" outlined :label="t('admin.fileSubmission')" :options="policyOptions" emit-value map-options /></div><q-input v-model="settings.moderation.automatic.externalApiUrl" outlined :label="t('admin.automaticReviewApi')" class="q-mt-md" /><div class="row q-col-gutter-md q-mt-sm"><q-select v-model="settings.moderation.automatic.failMode" class="col-12 col-md-4" outlined :label="t('admin.apiFailureMode')" :options="[{ label: t('admin.manualReview'), value: 'manual' }, { label: t('admin.autoReject'), value: 'reject' }]" emit-value map-options /><q-input v-model.number="settings.moderation.automatic.maxFileSize" class="col-12 col-md-4" type="number" outlined :label="t('admin.maxFileSize')" /><q-input v-model="blockedExtensionsText" class="col-12 col-md-4" outlined :label="t('admin.blockedExtensions')" /></div><div class="q-mt-sm"><q-toggle v-model="settings.moderation.automatic.requireHashes" :label="t('admin.requireHash')" /><q-toggle v-model="settings.moderation.automatic.requireSource" class="q-ml-md" :label="t('admin.requireSource')" /></div><div class="text-h6 q-mt-lg q-mb-sm">{{ t('admin.mojangSync') }}</div><q-toggle v-model="settings.mojang.enabled" color="positive" :label="t('admin.enableMojang')" /><q-input v-model="settings.mojang.clientId" outlined class="q-mt-sm" :label="t('admin.microsoftClientId')" :hint="t('admin.azureClientIdHint')" /><q-select v-model="settings.mojang.tenant" outlined emit-value map-options :label="t('admin.tenantType')" :options="[{ label: t('admin.tenantConsumers'), value: 'consumers' }, { label: t('admin.tenantCommon'), value: 'common' }, { label: t('admin.tenantOrganizations'), value: 'organizations' }]" /><div class="text-caption text-grey-7 q-mb-md">{{ t('admin.oauthEncryptionHint') }}</div><div class="text-h6 q-mt-lg q-mb-sm">{{ t('admin.yggAuth') }}</div><q-toggle v-model="settings.ygg.enabled" color="positive" :label="t('admin.enableYgg')" /><q-toggle v-model="settings.ygg.allowLocalAccounts" class="q-ml-md" :label="t('admin.allowLocalLogin')" /><div v-if="auth.isRoot" class="row q-col-gutter-md q-mt-sm"><q-input v-model.number="settings.ygg.accessTokenTtlSeconds" type="number" min="300" max="86400" class="col-12 col-md-6" outlined :label="t('admin.accessTokenTtl')" :hint="t('admin.secondsRange300')" /><q-input v-model.number="settings.ygg.refreshTokenTtlSeconds" type="number" min="3600" max="31536000" class="col-12 col-md-6" outlined :label="t('admin.refreshTokenTtl')" :hint="t('admin.lifecycleValidation')" /></div><q-input v-model="yggUpstreamsText" type="textarea" autogrow outlined class="q-mt-sm" :label="t('admin.upstreamsJson')" :hint="t('admin.upstreamsHint')" /><div v-if="auth.isRoot" class="row q-gutter-sm q-mt-lg"><q-btn outline color="secondary" icon="download" :label="t('admin.exportDatabase')" @click="exportDatabase" /><q-file v-model="importBundleFile" accept="application/json,.modpost.json" class="database-import-file" :label="t('admin.importBundle')" dense outlined @update:model-value="importDatabase" /></div><FormActions class="q-mt-md"><q-btn color="primary" :label="t('admin.saveSettings')" :loading="settingsSaving" @click="saveSettings" /></FormActions></div></q-tab-panel></q-tab-panels></q-card>
    </div>
  </q-page>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import type { SiteSettings } from '@andrea/contracts'
import { applySiteAppearance } from '../lib/site-settings'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { adminAccounts, adminOverview, adminProjects, deleteAccount, updateAccountRole, updateAccountVerification, updateMinecraftProfile, adminReviews, reviewProject, reviewFile, adminSettings, updateAdminSettings, type ReviewItem } from '../lib/admin'

import FormActions from '../components/FormActions.vue'
import { useI18n } from '../i18n'

const { t, locale, projectTypeLabel, statusLabel, roleLabel, reviewTypeLabel } = useI18n(); const router = useRouter(); const auth = useAuthStore(); const tab = ref('projects'); const loading = ref(false); const error = ref(''); const overview = ref({ accounts: 0, projects: 0, versions: 0, files: 0, downloads: 0, favorites: 0, topDownloads: [] as Array<{ projectSlug: string; count: number }>, topFavorites: [] as Array<{ projectSlug: string; count: number }> }); const accounts = ref<any[]>([]); const projects = ref<any[]>([]); const reviews = ref<ReviewItem[]>([]); const settings = ref<SiteSettings | null>(null); const settingsSaving = ref(false); const importBundleFile = ref<File | null>(null)
const metrics = computed(() => [{ label: t('admin.metricAccounts'), value: overview.value.accounts, caption: t('admin.registeredAccounts'), icon: 'people', tone: 'green' }, { label: t('admin.metricProjects'), value: overview.value.projects, caption: t('admin.publicProjects'), icon: 'inventory_2', tone: 'blue' }, { label: t('admin.metricVersions'), value: overview.value.versions, caption: t('admin.downloadableVersions'), icon: 'new_releases', tone: 'purple' }, { label: t('admin.metricFiles'), value: overview.value.files, caption: t('admin.hostedAndExternalFiles'), icon: 'cloud_download', tone: 'orange' }, { label: t('admin.metricDownloads'), value: overview.value.downloads, caption: t('admin.realDownloadEvents'), icon: 'download', tone: 'orange' }, { label: t('admin.metricFavorites'), value: overview.value.favorites, caption: t('admin.favoriteRecords'), icon: 'favorite', tone: 'pink' }])
const overviewBars = computed(() => { const max = Math.max(overview.value.accounts, overview.value.projects, overview.value.versions, overview.value.files, 1); return [{ label: t('admin.metricProjects'), value: overview.value.projects, ratio: overview.value.projects / max, color: 'primary' }, { label: t('admin.metricVersions'), value: overview.value.versions, ratio: overview.value.versions / max, color: 'deep-purple-4' }, { label: t('admin.metricFiles'), value: overview.value.files, ratio: overview.value.files / max, color: 'orange-5' }, { label: t('admin.metricAccounts'), value: overview.value.accounts, ratio: overview.value.accounts / max, color: 'light-blue-4' }] })
const accountColumns = computed(() => [{ name: 'email', label: t('admin.email'), field: 'email', align: 'left' as const }, { name: 'role', label: t('admin.role'), field: (row: any) => roleLabel(row.role), align: 'left' as const }, { name: 'createdAt', label: t('admin.createdAt'), field: 'createdAt', align: 'left' as const }, { name: 'actions', label: t('admin.actions'), field: 'actions', align: 'right' as const }]); const projectColumns = computed(() => [{ name: 'title', label: t('admin.projects'), field: 'title', align: 'left' as const }, { name: 'type', label: t('admin.type'), field: (row: any) => projectTypeLabel(row.type), align: 'left' as const }, { name: 'versions', label: t('admin.metricVersions'), field: (row: any) => row.versions?.length ?? 0, align: 'left' as const }, { name: 'actions', label: t('admin.actions'), field: 'actions', align: 'right' as const }])
const policyOptions = computed(() => [{ label: t('admin.noReview'), value: 'none' }, { label: t('admin.automaticReview'), value: 'automatic' }, { label: t('admin.fullManualReview'), value: 'full' }])
const blockedExtensionsText = computed({ get: () => settings.value?.moderation.automatic.blockedExtensions.join(', ') ?? '', set: (value: string) => { if (settings.value) settings.value.moderation.automatic.blockedExtensions = value.split(',').map((item) => item.trim().toLowerCase().replace(/^\./u, '')).filter(Boolean) } }); const registrationCodesText = computed({ get: () => settings.value?.registration.inviteCodes.join(', ') ?? '', set: (value: string) => { if (settings.value) settings.value.registration.inviteCodes = value.split(',').map((item) => item.trim()).filter(Boolean) } })
const yggUpstreamsText = ref('')
const nextRole = (role: string): 'user' | 'developer' | 'admin' | 'root' => role === 'user' ? 'developer' : role === 'developer' ? 'admin' : 'user'
const nextRoleLabel = (role: string) => ({ user: t('admin.setDeveloper'), developer: t('admin.setAdmin'), admin: t('admin.setUser'), root: t('account.role.root') }[role] ?? t('admin.setDeveloper'))
const changeRole = async (account: any) => { const role = nextRole(account.role); try { await updateAccountRole(account.id, role); account.role = role } catch { error.value = t('admin.roleUpdateFailed') } }; const approveAccount = async (account: any) => { try { const result = await updateAccountVerification(account.id, true); account.verifiedAt = result.verifiedAt } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.accountReviewFailed') } }; const editMinecraftUuid = async (account: any) => { const metadata = account.metadata ?? {}; const uuid = window.prompt(t('admin.uuidPrompt'), metadata.minecraftUuid ?? ''); if (!uuid) return; const skinUrl = window.prompt(t('admin.skinUrlPrompt'), metadata.skinUrl ?? '') ?? ''; const capeUrl = window.prompt(t('admin.capeUrlPrompt'), metadata.capeUrl ?? '') ?? ''; try { const result = await updateMinecraftProfile(account.id, { uuid, skinUrl: skinUrl.trim() || null, capeUrl: capeUrl.trim() || null, source: 'local' }); account.metadata = { ...metadata, minecraftUuid: result.minecraftUuid, skinUrl: skinUrl.trim() || null, capeUrl: capeUrl.trim() || null, uuidSource: 'local' } } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.uuidUpdateFailed') } }; const removeAccount = async (account: any) => { if (!window.confirm(t('admin.confirmDeleteAccount', { email: account.email }))) return; try { await deleteAccount(account.id); accounts.value = accounts.value.filter((item) => item.id !== account.id); overview.value.accounts -= 1 } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.accountDeleteFailed') } }
const loadReviews = async () => { try { reviews.value = (await adminReviews()).reviews } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.reviewQueueFailed') } }
const decide = async (item: ReviewItem, decision: 'approve' | 'reject') => { try { if (item.type === 'project') await reviewProject(item.slug, decision); else await reviewFile(item.id, decision); reviews.value = reviews.value.filter((candidate) => candidate.id !== item.id || candidate.type !== item.type) } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.reviewFailed') } }
const saveSettings = async () => { if (!settings.value) return; try { const parsed = JSON.parse(yggUpstreamsText.value); if (!Array.isArray(parsed)) throw new Error(t('admin.upstreamsMustBeArray')); settings.value.ygg.upstreams = parsed } catch (cause) { error.value = cause instanceof Error ? t('admin.upstreamsInvalidReason', { reason: cause.message }) : t('admin.upstreamsInvalid'); return } settingsSaving.value = true; try { settings.value = (await updateAdminSettings(settings.value)).settings; yggUpstreamsText.value = JSON.stringify(settings.value.ygg.upstreams, null, 2); applySiteAppearance(settings.value.appearance) } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.settingsSaveFailed') } finally { settingsSaving.value = false } }
const exportDatabase = async () => { const password = window.prompt(t('admin.backupPasswordPrompt')); if (!password) return; try { const response = await fetch('/api/v1/admin/database/export', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json', 'Accept-Language': locale.value }, body: JSON.stringify({ password }) }); if (!response.ok) { const result = await response.json().catch(() => ({})); throw new Error(result.error?.message ?? t('admin.backupExportFailed')) } const blob = new Blob([JSON.stringify(await response.json(), null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `andrea-modpost-${new Date().toISOString().slice(0, 10)}.modpost.json`; anchor.click(); URL.revokeObjectURL(url) } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.backupExportFailed') } }
const importDatabase = async (value: File | File[] | null) => { const file = Array.isArray(value) ? value[0] : value; if (!file) return; if (!window.confirm(t('admin.importConfirm'))) return; const password = window.prompt(t('admin.importPasswordPrompt')); if (!password) return; try { const bundle = JSON.parse(await file.text()); bundle.password = password; const response = await fetch('/api/v1/admin/database/import', { method: 'POST', credentials: 'include', headers: { 'Content-Type': 'application/json', 'Accept-Language': locale.value }, body: JSON.stringify(bundle) }); const result = await response.json(); if (!response.ok) throw new Error(result.error?.message ?? t('admin.backupImportFailed')); error.value = t('admin.importComplete', { createdAccounts: result.summary.createdAccounts, updatedAccounts: result.summary.updatedAccounts, createdProjects: result.summary.createdProjects, updatedProjects: result.summary.updatedProjects }) } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.backupImportFailed') } finally { importBundleFile.value = null } }
const load = async () => { loading.value = true; error.value = ''; try { const [summary, projectResult] = await Promise.all([adminOverview(), adminProjects()]); overview.value = summary; projects.value = projectResult.projects; if (auth.isAdmin) { accounts.value = (await adminAccounts()).accounts; reviews.value = (await adminReviews()).reviews; settings.value = (await adminSettings()).settings; yggUpstreamsText.value = JSON.stringify(settings.value.ygg.upstreams, null, 2) } } catch (cause) { error.value = cause instanceof Error ? cause.message : t('admin.loadFailed'); if (!auth.canPublish) await router.replace('/auth') } finally { loading.value = false } }
onMounted(async () => { await auth.load(); if (!auth.canPublish) return router.replace('/auth'); await load() })
</script>
